(function(root){'use strict';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const G=()=>root.THLaundryGuide,S=()=>root.THLaundryScenarios,U=()=>root.THLaundryUI;
const time=v=>v?new Date(v).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'}):'';
function summary(o,m,accounting={}){const ss=G().steps(o,m.role),done=ss.filter(s=>s.state==='done').length,total=ss.filter(s=>s.state!=='skip').length;return `<div class="order-progress"><span>${done} dari ${total} langkah selesai</span><progress max="${total}" value="${done}" aria-label="Langkah pesanan selesai"></progress><span>${ss.at(-1).state==='done'?'Barang dan dana sudah terselesaikan':'Ikuti bagian Kerjakan sekarang di bawah.'}</span></div>`;}
function checklist(o,m,actions){const steps=G().steps(o,m.role);return `<details class="card guide-checklist"><summary>Semua langkah penyelesaian <span class="section-hint">Lihat urutan & penanggung jawab</span></summary><p class="muted">Ini ringkasan perjalanan pesanan. Kerjakan melalui bagian “Kerjakan sekarang”. Langkah wajib mengikuti kondisi barang dan pembayaran; tugas orang lain tetap terlihat.</p><ol class="guide-steps">${steps.map(s=>`<li data-guide-step class="guide-step ${s.state}"><span class="step-number" aria-label="${s.state==='done'?'Selesai':s.state==='skip'?'Tidak diperlukan':'Langkah '+s.number}">${s.state==='done'?'✓':s.state==='skip'?'–':s.number}</span><div><div class="row spread"><strong>${E(s.title)}</strong><span class="role-chip">${E(s.role==='Sistem'?'Otomatis':s.role)}</span></div><p>${E(s.text)}</p><small class="${s.state==='done'?'success-text':''}">${s.state==='done'?'Selesai'+(s.actor?' · '+E(s.actor):''):s.state==='skip'?'Tidak diperlukan untuk pesanan ini.':s.id==='close'?'Diperiksa otomatis setelah barang dan dana selesai.':actions.includes(s.action)?'Wajib diselesaikan · tersedia untuk akun Anda':'Wajib diselesaikan · menunggu tahap sebelumnya atau petugas terkait'}</small></div></li>`).join('')}</ol></details>`;}
function report(o,accounting={}){return `<details class="card"><summary>Jurnal & laporan <span class="section-hint">Pesanan tercatat otomatis</span></summary><p>Pesanan sudah tampil di jurnal usaha.</p><p>${E(accounting.status||'Status pembukuan sedang diperiksa')} · ${accounting.posted||0} dari ${accounting.expected||0} catatan keuangan dibukukan.</p><a class="button" href="/?view=finance&order=${encodeURIComponent(o.id)}">Periksa laporan pesanan</a>${o.linkedThl?`<a class="button" href="/laundry-desk?order=${encodeURIComponent(o.linkedThl)}">Buka pesanan ${E(o.linkedThl)}</a>`:''}</details>`;}
function scenarioCard(s,o,m,active){const reviews=o?.sopReviews||[],key=o?G().reviewKey(o):'',state=r=>r.signature===key?'Sudah diperiksa':'Periksa ulang · order berubah';return `<details class="scenario-card" data-scenario="${s.id}" data-related="${active}"><summary><span class="scenario-number">${s.id}</span><span>${E(s.title)}</span>${active?'<span class="role-chip">Terkait order</span>':''}</summary>${s.limit?`<p class="alert warning">${E(s.limit)}</p>`:''}<div class="scenario-roles">${[['operator','Operator'],['owner','Owner'],...(m?.role==='Finance'?[['owner','Finance']]:[])].map(([keyName,role])=>{const r=reviews.find(x=>x.scenarioId===s.id&&x.role===role);return `<section><h3>${role}</h3><ol>${s[keyName].map(step=>`<li>${E(step)}</li>`).join('')}</ol>${r?`<p class="review-receipt ${r.signature===key?'success':'warning'}"><strong>${E(state(r))}</strong><br>${E(r.name)} · ${E(time(r.at))}<br>${E(r.note)}</p>`:'<p class="muted">Belum ada catatan pemeriksaan peran ini.</p>'}</section>`;}).join('')}</div><p><strong>Bukti yang diperiksa</strong></p><ul>${s.evidence.map(e=>`<li>${E(e)}</li>`).join('')}</ul><div class="scenario-closure"><strong>Kondisi penyelesaian</strong><p>${E(s.closure)}</p></div>${o?`<button data-sop-review="${s.id}">Catat pemeriksaan ${E(m.role)}</button>`:''}</details>`;}
function scenarios(o,m){const related=G().related(o);return `<details class="card scenario-library"><summary>Panduan jika ada kendala <span class="section-hint">Buka hanya saat diperlukan</span></summary><h2>Cari kondisi yang sedang dihadapi</h2><p class="muted">Buka skenario yang sesuai. “Sudah diperiksa” adalah catatan petugas, bukan tanda order otomatis selesai.</p><div class="scenario-controls"><label>Cari kondisi<input data-scenario-search type="search" placeholder="Batal, label, refund, setoran…"></label><label>Tampilkan<select data-scenario-scope><option value="related">Terkait order ini</option><option value="all">Semua 28 skenario</option></select></label></div><p data-scenario-empty hidden>Tidak ada skenario yang cocok. Tampilkan semua atau ganti pencarian.</p>${S().map(s=>scenarioCard(s,o,m,related.includes(s.id))).join('')}</details>`;}
function filter(scope=document){const q=(scope.querySelector('[data-scenario-search]')?.value||'').toLowerCase(),mode=scope.querySelector('[data-scenario-scope]')?.value||'all';let count=0;scope.querySelectorAll('[data-scenario]').forEach(el=>{el.hidden=(mode==='related'&&el.dataset.related!=='true')||!el.textContent.toLowerCase().includes(q);if(!el.hidden)count++;});const empty=scope.querySelector('[data-scenario-empty]');if(empty)empty.hidden=count>0;}
function bind(o,m,handlers){document.querySelectorAll('[data-guide-action]').forEach(b=>b.onclick=()=>handlers.action(b.dataset.guideAction));document.querySelector('[data-guide-link]')?.addEventListener('click',handlers.link);document.querySelectorAll('[data-sop-review]').forEach(b=>b.onclick=()=>handlers.review(b.dataset.sopReview));document.querySelector('[data-guide-role]')?.addEventListener('change',e=>document.querySelectorAll('[data-guide-step]').forEach(row=>row.hidden=e.target.value==='mine'&&row.dataset.mine!=='true'));document.querySelector('[data-scenario-search]')?.addEventListener('input',()=>filter());document.querySelector('[data-scenario-scope]')?.addEventListener('change',()=>filter());filter();}
function library(){const modal=document.querySelector('#modal');modal.innerHTML=`<div class="row spread"><h2>Panduan 28 skenario SOP v0.4</h2><button data-library-close>Tutup</button></div><p>Buka order untuk melihat checklist sesuai kondisi dan mencatat pemeriksaan atas nama akun Anda.</p><label>Cari kondisi<input type="search" data-scenario-search placeholder="Cari nomor atau kondisi…"></label>${S().map(s=>scenarioCard(s,null,null,false)).join('')}`;modal.showModal();modal.querySelector('[data-library-close]').onclick=()=>modal.close();modal.querySelector('[data-scenario-search]').oninput=()=>filter(modal);}
root.THLaundryGuideUI={summary,checklist,report,scenarios,bind,library};
})(window);
